examples:
Python retry_guard example:
from redwood import Client, retry_guard
client = Client()

@retry_guard(max_retries=3)
def call_generate(payload):
    return client.generate(payload)

try:
    res = call_generate({
        'prompt': 'Summarize the meeting'
    })
except TransientError as e:
    # e.code == 'ERR_TRANSIENT.SERVER_OVERLOAD'
    print(e.hint or 'Try again in a few seconds')

TypeScript usage example:
import {Client, withRetryGuard, TransientError} from '@redwood/sdk'
const client = new Client()
const guarded = withRetryGuard(client.generate.bind(client), {maxRetries: 4})
try {
  const r = await guarded({prompt: 'Explain GC in 3 lines'})
} catch (e) {
  if (e instanceof TransientError) {
    console.log(e.hint)
  }
}

Go resume example:
cli, _ := newClient()
stream, _ := cli.StartChat(ctx, req)
for {
  msg, meta, err := stream.RecvWithMeta(ctx)
  if err != nil {
    if si, ok := err.(StreamInterrupted); ok {
      // attempt resume
      newStream, err2 := cli.ResumeChat(ctx, si.ResumeToken)
      if err2 == nil {
        stream = newStream
        continue
      }
    }
    return err
  }
  fmt.Println(msg)
}
